package main

// Managed Caddy (docs/DESIGN_MANAGED_STACKS.md 4.1): an image with the Cloudflare DNS and Coraza
// WAF modules built from the Dockerfile below, Caddyfile generated by Gilmok as usual.
//
//   <data>/stacks/caddy/
//     Dockerfile  compose.yml  .env (0600, CLOUDFLARE_API_TOKEN)
//     conf/   → /etc/caddy   Caddyfile, certs/cf-origin-pull-ca.pem
//     data/   → /data        certificates
//     config/ → /config
//
// The admin API (:2019) is not published: in Docker mode Gilmok validates and reloads with
// `docker exec`, and an open admin API would let any container on the network reconfigure Caddy.

import (
	"context"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"fmt"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

const caddyDockerfile = `# 길목이 만든 파일입니다 (관리형 Caddy) — Cloudflare DNS + Coraza WAF(OWASP CRS)
FROM caddy:builder AS builder
RUN xcaddy build \
    --with github.com/caddy-dns/cloudflare \
    --with github.com/corazawaf/coraza-caddy/v2

FROM caddy:latest
COPY --from=builder /usr/bin/caddy /usr/bin/caddy
`

// Cloudflare's published IPv4 ranges (https://www.cloudflare.com/ips-v4)
const cloudflareIPv4 = "173.245.48.0/20 103.21.244.0/22 103.22.200.0/22 103.31.4.0/22 141.101.64.0/18 108.162.192.0/18 190.93.240.0/20 188.114.96.0/20 197.234.240.0/22 198.41.128.0/17 162.158.0.0/15 104.16.0.0/13 104.24.0.0/14 172.64.0.0/13 131.0.72.0/22"

const caddyCAPath = "/etc/caddy/certs/cf-origin-pull-ca.pem"

func init() {
	stackKinds["caddy"] = &stackKind{
		Label: "Caddy", DefaultName: "gilmok-caddy", Project: "gilmok-caddy", Service: "caddy", build: true,
		ports: caddyPorts, render: renderCaddyStack, verify: verifyCaddyStack, adopt: adoptCaddyStack, check: checkCaddyOptions,
	}
}

// caddyPrivBind: where the private listener is published, by how private clients arrive.
// tailscale serve on the host hands over to 127.0.0.1 (nothing else can reach it); clients that
// come to the Tailscale IP directly need that address; another VPN gets all interfaces.
func caddyPrivBind(st Settings) string {
	switch st.TopoPrivKind {
	case "ts_direct":
		if net.ParseIP(st.TailscaleIP) != nil {
			return st.TailscaleIP
		}
		return "0.0.0.0"
	case "vpn":
		return "0.0.0.0"
	}
	return "127.0.0.1"
}

func caddyPrivOn(d Data) bool {
	if d.Settings.UseTailscale {
		return true
	}
	for _, s := range d.Services {
		if s.Exposure == ExposureTailscale {
			return true
		}
	}
	return false
}

// caddyPorts: "ip:port" on the host ("" ip = all interfaces).
func caddyPorts(a *App, o map[string]string) []string {
	d := a.store.Snapshot()
	p := []string{":" + o["httpsPort"]}
	if o["open80"] == "1" {
		p = append(p, ":80")
	}
	if caddyPrivOn(d) {
		p = append(p, caddyPrivBind(d.Settings)+":"+strconv.Itoa(d.Settings.TailscalePort))
	}
	return p
}

func checkCaddyOptions(a *App, o map[string]string) error {
	if o["httpsPort"] == "" {
		o["httpsPort"] = "443"
	}
	if n, err := strconv.Atoi(o["httpsPort"]); err != nil || n < 1 || n > 65535 {
		return errors.New("HTTPS 포트는 1~65535 사이여야 합니다")
	}
	if o["tls"] != "internal" {
		o["tls"] = "acme"
	}
	if o["open80"] != "1" {
		o["open80"] = ""
	}
	if ca := strings.TrimSpace(o["fileCaPem"]); ca != "" {
		if err := checkCAPEM(ca); err != nil {
			return err
		}
	}
	return nil
}

func checkCAPEM(s string) error {
	b, _ := pem.Decode([]byte(s))
	if b == nil || b.Type != "CERTIFICATE" {
		return errors.New("인증된 원본 풀 CA는 PEM 인증서(-----BEGIN CERTIFICATE-----)여야 합니다")
	}
	if _, err := x509.ParseCertificate(b.Bytes); err != nil {
		return fmt.Errorf("CA 인증서를 읽지 못했습니다: %v", err)
	}
	return nil
}

// managedCaddyBase: global options + the snippets the generated sites import.
func managedCaddyBase(st Settings, o map[string]string, hasToken bool) string {
	var g []string
	if o["tls"] == "internal" {
		g = append(g, "\tlocal_certs")
	} else if hasToken && st.UseCloudflare {
		g = append(g, "\tacme_dns cloudflare {env.CLOUDFLARE_API_TOKEN}")
	}
	if st.UseCloudflare {
		g = append(g, "\tservers {\n\t\ttrusted_proxies static "+cloudflareIPv4+"\n\t\tclient_ip_headers CF-Connecting-IP\n\t}")
	}
	var sb strings.Builder
	sb.WriteString("# 길목이 설치한 Caddy (관리형) — 전역 옵션과 스니펫. Caddy 탭 › 전역 설정에서 고칠 수 있습니다.\n")
	if len(g) > 0 {
		sb.WriteString("{\n" + strings.Join(g, "\n") + "\n}\n")
	}
	auth := st.AutheliaCtr
	if auth == "" {
		auth = "authelia"
	}
	sb.WriteString(`
# Cloudflare 인증된 원본 풀(mTLS): 내 Cloudflare 존을 거친 요청만 허용 — Proxied 사이트에만 import
(` + snippetMTLS + `) {
	tls {
		client_auth {
			mode require_and_verify
			trust_pool file ` + caddyCAPath + `
		}
	}
}

(` + snippetAuthelia + `) {
	forward_auth ` + auth + `:9091 {
		uri /api/authz/forward-auth
		copy_headers Remote-User Remote-Groups Remote-Name Remote-Email
	}
}
`)
	return sb.String()
}

func yq(s string) string { return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s) + `"` }

func renderCaddyStack(a *App, o map[string]string, dir, host, network, ctr string, log func(string, ...any)) error {
	for _, sub := range []string{"conf/certs", "data", "config"} {
		if err := os.MkdirAll(filepath.Join(dir, sub), 0o755); err != nil {
			return err
		}
	}
	if err := os.WriteFile(filepath.Join(dir, "Dockerfile"), []byte(caddyDockerfile), 0o644); err != nil {
		return err
	}
	if ca := strings.TrimSpace(o["fileCaPem"]); ca != "" {
		if err := os.WriteFile(filepath.Join(dir, "conf", "certs", "cf-origin-pull-ca.pem"), []byte(ca+"\n"), 0o644); err != nil {
			return err
		}
		log("  인증된 원본 풀 CA 저장")
	}
	tok := cfToken()
	if err := writeCaddyEnv(dir, tok); err != nil {
		return err
	}
	// base skeleton: Gilmok's own when there is none yet; an imported one is kept but made to fit this
	// container (CA path, Authelia address, DNS certificates, missing cf_only / authelia snippets)
	if strings.TrimSpace(a.store.Snapshot().Settings.CaddyBase) != "" {
		_ = a.store.Update(func(d *Data) error {
			// the record is written after the install: fit as if this container were the managed one
			x := *d
			if x.Stacks == nil || x.Stacks["caddy"] == nil {
				x.Stacks = map[string]*ManagedStack{"caddy": {Name: "caddy", Container: ctr, Dir: dir}}
				for k, v := range d.Stacks {
					x.Stacks[k] = v
				}
			}
			if nb, changes := fitManagedBase(&x, tok != ""); len(changes) > 0 {
				d.Settings.CaddyBase = nb
				log("  가져온 기본 골격을 이 Caddy에 맞춤: %s", strings.Join(changes, ", "))
			}
			return nil
		})
	}
	if strings.TrimSpace(a.store.Snapshot().Settings.CaddyBase) == "" {
		st := a.store.Snapshot().Settings
		base := managedCaddyBase(st, o, tok != "")
		if err := a.store.Update(func(d *Data) error { d.Settings.CaddyBase = base; return nil }); err != nil {
			return err
		}
		log("  기본 골격(전역 옵션·cf_only·authelia 스니펫) 만듦")
	}
	d := a.store.Snapshot()
	if err := os.WriteFile(filepath.Join(dir, "conf", "Caddyfile"), []byte(GenerateCaddyfile(d)), 0o644); err != nil {
		return err
	}
	log("  Caddyfile 생성 (서비스 %d개)", len(d.Services))

	ports := []string{yq(o["httpsPort"] + ":443")}
	if o["open80"] == "1" {
		ports = append(ports, yq("80:80"))
	}
	if caddyPrivOn(d) {
		tp := strconv.Itoa(d.Settings.TailscalePort)
		ports = append(ports, yq(caddyPrivBind(d.Settings)+":"+tp+":"+tp))
	}
	compose := `# 길목이 만든 파일입니다 (관리형 Caddy). 직접 고치면 다시 설치할 때 덮어써집니다.
name: ` + stackProject(ctr) + `
services:
  caddy:
    build: .
    image: gilmok-caddy:local
    container_name: ` + ctr + `
    restart: unless-stopped
    labels:
      gilmok.managed: caddy
    environment:
      CLOUDFLARE_API_TOKEN: ${CLOUDFLARE_API_TOKEN:-}
    # Linux: host.docker.internal (published ports of other containers / host services) is not
    # defined by default — Docker Desktop has it built in
    extra_hosts:
      - "host.docker.internal:host-gateway"
    ports:
      - ` + strings.Join(ports, "\n      - ") + `
    volumes:
      - ` + yq(host+"/conf:/etc/caddy") + `
      - ` + yq(host+"/data:/data") + `
      - ` + yq(host+"/config:/config") + `
    logging:
      options: { max-size: "10m", max-file: "3" }
    networks: [edge]
networks:
  edge:
    name: ` + network + `
    external: true
`
	return os.WriteFile(filepath.Join(dir, "compose.yml"), []byte(compose), 0o644)
}

// writeCaddyEnv keeps the Cloudflare token in the stack's .env (0600), so a plain
// `docker compose up` on the host recreates Caddy with the same token.
func writeCaddyEnv(dir, tok string) error {
	p := filepath.Join(dir, ".env")
	if err := os.WriteFile(p+".tmp", []byte("# 길목이 관리합니다 — Cloudflare 토큰을 바꾸면 다시 써집니다\nCLOUDFLARE_API_TOKEN="+tok+"\n"), 0o600); err != nil {
		return err
	}
	return os.Rename(p+".tmp", p)
}

func verifyCaddyStack(a *App, ctr string) error {
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	out, err := docker(ctx, nil, nil, "exec", ctr, "caddy", "validate", "--config", "/etc/caddy/Caddyfile", "--adapter", "caddyfile")
	if err != nil {
		return fmt.Errorf("Caddyfile 검증 실패: %s", oneLine(caddyErr(out)))
	}
	return nil
}

func adoptCaddyStack(d *Data, rec *ManagedStack) {
	st := &d.Settings
	st.UseCaddy, st.CaddyMode, st.CaddyContainer = true, "docker", rec.Container
	st.CaddyfilePath = filepath.Join(rec.Dir, "conf", "Caddyfile")
	st.CaddyfileInCtr = "/etc/caddy/Caddyfile"
	st.CaddyStackDir, st.CaddyService = "", "caddy"
}

// reCertConfigured: the Caddyfile already says how certificates are obtained (DNS challenge,
// internal CA or certificate files) — then nothing needs adding.
var reCertConfigured = regexp.MustCompile(`(?m)acme_dns|\bdns\s+cloudflare|local_certs|\btls\s+internal|\btls\s+\S+\.(pem|crt)\b`)

// ensureAcmeDNS adds `acme_dns cloudflare {env.CLOUDFLARE_API_TOKEN}` to the global options of a base
// configuration that has no certificate method yet. Sites behind the Cloudflare proxy cannot pass the
// HTTP-01 / TLS-ALPN challenges (Cloudflare answers them), so they need the DNS challenge.
func ensureAcmeDNS(base string) (string, bool) {
	if reCertConfigured.MatchString(base) {
		return base, false
	}
	const line = "\tacme_dns cloudflare {env.CLOUDFLARE_API_TOKEN}"
	lines := strings.Split(base, "\n")
	for i, l := range lines {
		t := strings.TrimSpace(l)
		if t == "" || strings.HasPrefix(t, "#") {
			continue
		}
		if t == "{" { // the global options block comes first
			out := append([]string{}, lines[:i+1]...)
			out = append(out, line)
			out = append(out, lines[i+1:]...)
			return strings.Join(out, "\n"), true
		}
		break
	}
	// no global block: put one at the top (after leading comments)
	i := 0
	for i < len(lines) && (strings.TrimSpace(lines[i]) == "" || strings.HasPrefix(strings.TrimSpace(lines[i]), "#")) {
		i++
	}
	out := append([]string{}, lines[:i]...)
	out = append(out, "{", line, "}", "")
	out = append(out, lines[i:]...)
	return strings.Join(out, "\n"), true
}

// caddyTokenChanged: the Cloudflare token was saved / deleted — a managed Caddy gets the new
// .env and is recreated so DNS-01 renewals keep working.
// fixManagedCaddyACME: a managed Caddy installed before the Cloudflare token existed was set up for
// HTTP challenges, which fail behind the Cloudflare proxy (every Proxied site → 525). Once there is a
// token, switch its base configuration to the DNS challenge (pending until 「적용」). Runs when the
// token changes and at startup (installs made by older versions).
func (a *App) fixManagedCaddyACME() {
	if a.store.Snapshot().Stacks["caddy"] == nil {
		return
	}
	changed := false
	_ = a.store.Update(func(d *Data) error {
		if nb, changes := fitManagedBase(d, cfToken() != ""); len(changes) > 0 {
			d.Settings.CaddyBase = nb
			d.markDirty("관리형 Caddy 기본 골격 맞춤: " + strings.Join(changes, ", "))
			changed = true
		}
		return nil
	})
	if changed {
		a.logEvent("system", "info", "stack.token", "caddy", "관리형 Caddy의 기본 골격을 이 컨테이너에 맞췄습니다 — 「적용」하면 반영됩니다", nil)
	}
}

func (a *App) caddyTokenChanged(r interface{ Context() context.Context }) {
	rec := a.store.Snapshot().Stacks["caddy"]
	if rec == nil {
		return
	}
	a.fixManagedCaddyACME()
	if err := writeCaddyEnv(rec.Dir, cfToken()); err != nil {
		a.logEvent("system", "error", "stack.token", "caddy", "관리형 Caddy의 토큰 파일을 고치지 못했습니다: "+err.Error(), nil)
		return
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		defer cancel()
		if out, err := stackCompose(ctx, stackKinds["caddy"], rec.Dir, nil, "up", "-d"); err != nil {
			a.logEvent("system", "error", "stack.token", "caddy", "관리형 Caddy를 새 토큰으로 다시 만들지 못했습니다: "+oneLine(lastLines(out, 2)), nil)
		} else {
			a.logEvent("system", "info", "stack.token", "caddy", "관리형 Caddy에 바뀐 Cloudflare 토큰을 반영했습니다", nil)
		}
	}()
}

// caddyCAFile: where a managed Caddy's mTLS CA lives on Gilmok's side ("" = no managed Caddy).
func (a *App) caddyCAFile() string {
	rec := a.store.Snapshot().Stacks["caddy"]
	if rec == nil {
		return ""
	}
	return filepath.Join(rec.Dir, "conf", "certs", "cf-origin-pull-ca.pem")
}

// POST /api/stacks/caddy/ca {pem} — the Cloudflare Authenticated Origin Pulls CA for a managed Caddy
// (cf_only / mTLS sites). Without it every mTLS site fails validation.
func (a *App) postCaddyCA(w http.ResponseWriter, r *http.Request) {
	path := a.caddyCAFile()
	if path == "" {
		fail(w, 404, errors.New("길목이 설치한 Caddy가 없습니다 — 직접 운영하는 Caddy는 그 컨테이너에 CA 파일을 마운트하세요"))
		return
	}
	var in struct {
		PEM string `json:"pem"`
	}
	if err := readJSON(r, &in); err != nil {
		fail(w, 400, err)
		return
	}
	ca := strings.TrimSpace(in.PEM)
	if err := checkCAPEM(ca); err != nil {
		fail(w, 400, err)
		return
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		fail(w, 500, err)
		return
	}
	if err := os.WriteFile(path, []byte(ca+"\n"), 0o644); err != nil {
		fail(w, 500, err)
		return
	}
	a.auth.audit(r, "audit", "warn", "Caddy mTLS CA 저장", "caddy", "관리형 Caddy의 인증된 원본 풀 CA를 저장했습니다", nil)
	writeJSON(w, 200, map[string]any{"ok": true})
}

var reTrustPool = regexp.MustCompile(`(trust_pool\s+file\s+|trusted_ca_cert_file\s+)(\S+)`)

// fitManagedBase makes the base configuration fit a Caddy Gilmok installed. Typical source of a
// mismatch: a Caddyfile imported from another Caddy (its CA path, its Authelia name, no DNS
// certificates, a missing snippet). Returns the new base and what changed (none = nothing to do).
func fitManagedBase(d *Data, hasToken bool) (string, []string) {
	base := d.Settings.CaddyBase
	var changes []string
	if strings.TrimSpace(base) == "" || d.Stacks["caddy"] == nil {
		return base, nil
	}
	// the mTLS CA lives at conf/certs/ in a managed Caddy
	if nb := reTrustPool.ReplaceAllString(base, "${1}"+caddyCAPath); nb != base {
		base = nb
		changes = append(changes, "mTLS CA 경로 → "+caddyCAPath)
	}
	// forward_auth goes to the Authelia Gilmok installed
	if rec := d.Stacks["authelia"]; rec != nil {
		if m := reForwardAuth.FindStringSubmatch(base); m != nil && m[2] != rec.Container {
			base = reForwardAuth.ReplaceAllString(base, "${1}"+rec.Container+"${3}")
			changes = append(changes, "forward_auth → "+rec.Container)
		}
	}
	// certificates by DNS when the sites sit behind the Cloudflare proxy
	if hasToken && d.Settings.UseCloudflare {
		if nb, ok := ensureAcmeDNS(base); ok {
			base = nb
			changes = append(changes, "acme_dns 추가")
		}
	}
	// snippets the services need but the base does not define
	defined := map[string]bool{}
	for _, m := range reSnippetDef.FindAllStringSubmatch(base, -1) {
		defined[m[1]] = true
	}
	needMTLS, needAuth := false, false
	for _, s := range d.Services {
		if s.Enabled && !s.DNSOnly {
			needMTLS = needMTLS || (s.Exposure == ExposurePublic && s.Proxied && s.MTLS)
			needAuth = needAuth || s.Authelia.Enabled
		}
	}
	if needMTLS && d.Settings.UseCloudflare && !defined[snippetMTLS] {
		base = strings.TrimRight(base, "\n") + "\n\n(" + snippetMTLS + ") {\n\ttls {\n\t\tclient_auth {\n\t\t\tmode require_and_verify\n\t\t\ttrust_pool file " + caddyCAPath + "\n\t\t}\n\t}\n}\n"
		changes = append(changes, snippetMTLS+" 스니펫 추가")
	}
	if needAuth && d.Settings.UseAuthelia && !defined[snippetAuthelia] {
		auth := d.Settings.AutheliaCtr
		if rec := d.Stacks["authelia"]; rec != nil {
			auth = rec.Container
		}
		if auth == "" {
			auth = "authelia"
		}
		base = strings.TrimRight(base, "\n") + "\n\n(" + snippetAuthelia + ") {\n\tforward_auth " + auth + ":9091 {\n\t\turi /api/authz/forward-auth\n\t\tcopy_headers Remote-User Remote-Groups Remote-Name Remote-Email\n\t}\n}\n"
		changes = append(changes, snippetAuthelia+" 스니펫 추가")
	}
	return base, changes
}
